function ThresholdDetail() { const fields = [["Parameter", unavailable], ["Module", unavailable], ["Owner Rule ID", unavailable], ["Standard / Reference", unavailable], ["Rule Version", unavailable], ["Threshold Set", unavailable], ["Effective Scope", unavailable], ["Created", unavailable], ["Last Review", unavailable], ["Next Review", unavailable]]; return <aside className="rounded-xl border border-blue-100 bg-white p-4 dark:border-slate-800 dark:bg-slate-900"><div className="flex items-center justify-between"><div><h3 className="text-lg font-semibold text-blue-950 dark:text-white">Rule Details</h3><p className="mt-1 text-xs text-slate-500">Selected rule: {unavailable}</p></div><button type="button" disabled aria-label="Close rule details" className="text-slate-400 disabled:cursor-not-allowed"><X size={18} /></button></div><dl className="mt-4 space-y-2 text-xs">{fields.map(([label, value]) => <div className="grid grid-cols-[1fr_1fr] gap-2" key={label}><dt className="text-slate-500">{label}</dt><dd className="break-words font-medium text-blue-950 dark:text-slate-200">{value}</dd></div>)}</dl><div className="mt-4 border-t border-blue-100 pt-4"><h4 className="font-semibold text-blue-950 dark:text-white">Threshold Values</h4><div className="mt-2 grid grid-cols-2 gap-2"><div className="rounded-lg bg-amber-50 p-3"><p className="text-[10px] text-slate-500">Warning Limit</p><strong className="text-sm text-amber-700">{unavailable}</strong></div><div className="rounded-lg bg-red-50 p-3"><p className="text-[10px] text-slate-500">Critical Limit</p><strong className="text-sm text-red-700">{unavailable}</strong></div></div></div><div className="mt-4 border-t border-blue-100 pt-4"><div className="flex items-center justify-between"><h4 className="font-semibold text-blue-950 dark:text-white">Recent Trend (Last 12 months)</h4><span className="text-[10px] text-slate-500">Unit: {unavailable}</span></div><div className="mt-2 rounded-lg border border-blue-100 p-2"><svg aria-label="Threshold trend unavailable" className="h-32 w-full" viewBox="0 0 260 130" role="img"><path d="M28 10v95h220" fill="none" stroke="#cbd5e1" /><path d="M28 35h220M28 60h220M28 85h220" stroke="#e2e8f0" /><text x="3" y="18" fill="#64748b" fontSize="8">{unavailable}</text><text x="3" y="64" fill="#64748b" fontSize="8">{unavailable}</text><text x="3" y="110" fill="#64748b" fontSize="8">{unavailable}</text><text x="32" y="121" fill="#64748b" fontSize="8">{unavailable}</text><text x="112" y="121" fill="#64748b" fontSize="8">{unavailable}</text><text x="204" y="121" fill="#64748b" fontSize="8">{unavailable}</text></svg><div className="mt-2 flex flex-wrap gap-3 text-[10px] text-slate-500"><span>● Parameter: {unavailable}</span><span className="text-amber-600">— Warning Limit</span><span className="text-red-600">— Critical Limit</span></div><p className="mt-2 text-[10px] text-slate-500">No verified historical series available.</p></div></div><div className="mt-4 border-t border-blue-100 pt-4"><div className="flex items-center justify-between"><h4 className="font-semibold text-blue-950 dark:text-white">Impacted Assets</h4><button type="button" disabled className="text-xs font-semibold text-blue-700 disabled:cursor-not-allowed">View All</button></div><p className="mt-3 text-xs text-slate-500">{unavailable}</p></div></aside>; }

function WorkflowKpi({ icon, label, value, detail, tone }: { icon: React.ReactNode; label: string; value: string; detail: string; tone: "green" | "amber" | "red" | "slate" }) { const colors = { green: "bg-emerald-600", amber: "bg-amber-500", red: "bg-red-500", slate: "bg-slate-600" }; return <div className="flex min-h-[112px] items-center gap-3 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-lg text-white ${colors[tone]}`}>{icon}</div><div><p className="text-xs font-semibold text-blue-900 dark:text-blue-200">{label}</p><p className="mt-1 text-2xl font-bold text-blue-950 dark:text-white">{value}</p><p className="text-[10px] text-slate-500">{detail}</p></div></div>; }
