function RolesPermissions({ roles, missingFields, error, canView }: { roles: SettingsRole[]; missingFields: string[]; error: string | null; canView: boolean }) {
  const [selectedRole, setSelectedRole] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const roleRows = roles.filter((role) => role.name.toLowerCase().includes(query.toLowerCase()));
  const activeRole = roles.find((role) => role.name === selectedRole) ?? roleRows[0] ?? null;
  const modules = ["Dashboard", "Asset Master", "Integration Hub", "Documents", "Sensors", "SCADA", "CP", "Corrosion", "ECDA", "ILI", "Defect Manager", "Risk", "AI", "Reports", "Settings"];
  const actions = ["Create", "Read", "Edit", "Approve", "Export", "Delete"];
  useEffect(() => { if (roleRows.length && !selectedRole) setSelectedRole(roleRows[0].name); }, [roleRows, selectedRole]);
  return <div className="space-y-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5"><RoleKpi icon={<Users size={25} />} label="Total Roles" value={canView && !error ? String(roles.length) : unavailable} detail="Verified role records" tone="blue" /><RoleKpi icon={<ClipboardList size={25} />} label="Custom Roles" value={unavailable} detail="Role type unavailable" tone="slate" /><RoleKpi icon={<Cog size={25} />} label="Permission Sets" value={unavailable} detail="Permission contract unavailable" tone="green" /><RoleKpi icon={<LockKeyhole size={25} />} label="Restricted Roles" value={unavailable} detail="Restriction field unavailable" tone="red" /><RoleKpi icon={<ClockIcon size={25} />} label="Approval Required" value={unavailable} detail="Approval workflow unavailable" tone="blue" /></div><div className="grid min-w-0 gap-4 xl:grid-cols-[minmax(270px,0.72fr)_minmax(0,1.7fr)]"><section className="rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className="flex items-center justify-between gap-2"><h2 className="text-xl font-semibold text-blue-950 dark:text-white">Role Register</h2><ActionButton icon={<Plus size={16} />} label="Add Role" /></div><div className="mt-3 flex gap-2"><div className="flex min-w-0 flex-1 items-center gap-2 rounded-lg border border-blue-100 px-3 py-2 text-xs text-slate-500"><Search size={15} /><input aria-label="Search roles" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search roles..." className="min-w-0 flex-1 bg-transparent outline-none" /></div><FilterSelect label="All Roles" /></div>{!canView ? <p className="mt-4 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800">Admin access is required to view role administration.</p> : null}{error ? <p role="alert" className="mt-4 rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-700">{error}</p> : null}<div className="mt-4 divide-y divide-blue-50 dark:divide-slate-800">{canView && roleRows.map((role) => <button type="button" key={role.name} onClick={() => setSelectedRole(role.name)} className={`flex w-full items-center gap-3 px-2 py-3 text-left ${activeRole?.name === role.name ? "rounded-lg bg-blue-50" : ""}`}><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-blue-100 text-blue-700"><Shield size={18} /></div><span className="min-w-0 flex-1"><strong className="block text-sm text-blue-950 dark:text-white">{role.name}</strong><span className="block text-[11px] text-slate-500">Description: {unavailable}</span></span><span className="text-right text-[11px] text-slate-500"><span className="block">Users</span><strong className="text-blue-950 dark:text-white">{role.userCount}</strong></span></button>)}{canView && !roleRows.length ? <p className="p-5 text-center text-xs text-slate-500">No verified role records available.</p> : null}</div><p className="mt-4 text-xs text-slate-500">Showing {roleRows.length} of {roles.length} roles</p></section><section className="min-w-0 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-blue-100 text-blue-700"><Shield size={21} /></div><div><h2 className="text-xl font-semibold text-blue-950 dark:text-white">{activeRole?.name ?? unavailable}</h2><p className="text-xs text-slate-500">Role type: {unavailable}</p></div></div><div className="flex gap-2"><ActionButton icon={<ClipboardList size={15} />} label="Clone Role" /><ActionButton icon={<Users size={15} />} label="Assign Users" /><ActionButton icon={<ClipboardList size={15} />} label="Permission Templates" /><IconButton icon={<MoreVertical size={17} />} label="More role actions" /></div></div><div className="mt-4 flex overflow-x-auto border-b border-blue-100 text-xs font-semibold text-blue-700">{["Permissions", "Assigned Users", "Approval Workflow", "Role Details"].map((label, index) => <button type="button" key={label} disabled={index !== 0} className={`whitespace-nowrap border-b-2 px-4 py-3 ${index === 0 ? "border-blue-600" : "border-transparent opacity-60"}`}>{label}{index === 1 ? ` (${unavailable})` : ""}</button>)}</div><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[850px] text-left text-xs"><thead className="bg-blue-50/70 text-blue-950 dark:bg-slate-800 dark:text-slate-200"><tr><th className="p-2">Module</th>{actions.map((action) => <th className="p-2 text-center" key={action}>{action}</th>)}</tr></thead><tbody>{modules.map((module) => <tr key={module} className="border-b border-blue-50 dark:border-slate-800"><td className="p-2 font-semibold text-blue-950 dark:text-white">{module}</td>{actions.map((action) => <td className="p-2 text-center" key={action}><PermissionToggle label={`${module} ${action}`} /></td>)}</tr>)}</tbody></table></div><div className="mt-4 rounded-lg border border-blue-100 bg-blue-50/60 p-3 text-xs text-blue-800">Permission values, approval rules, and effective access are not available in the current backend contract. No UI toggle grants or changes access.</div><div className="mt-3 flex flex-wrap justify-end gap-2"><ActionButton icon={<Eye size={15} />} label="Preview Changes" /><ActionButton icon={<Mail size={15} />} label="Request Approval" /><ActionButton icon={<Shield size={15} />} label="Save Changes" /></div>{missingFields.length ? <p className="mt-3 text-xs text-slate-500">Missing fields: {missingFields.join(", ")}. Values are not inferred.</p> : null}</section></div></div>;
}

function RoleKpi({ icon, label, value, detail, tone }: { icon: React.ReactNode; label: string; value: string; detail: string; tone: "blue" | "slate" | "green" | "red" }) { const colors = { blue: "bg-blue-600", slate: "bg-slate-600", green: "bg-emerald-600", red: "bg-red-500" }; return <div className="flex min-h-[112px] items-center gap-3 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-lg text-white ${colors[tone]}`}>{icon}</div><div><p className="text-xs font-semibold text-blue-900 dark:text-blue-200">{label}</p><p className="mt-1 text-2xl font-bold text-blue-950 dark:text-white">{value}</p><p className="text-[10px] text-slate-500">{detail}</p></div></div>; }
function PermissionToggle({ label }: { label: string }) { return <button type="button" disabled aria-label={`${label}: ${unavailable}`} title="Permission contract unavailable; no access change is possible" className="mx-auto block h-5 w-9 rounded-full border border-slate-300 bg-slate-100 disabled:cursor-not-allowed disabled:opacity-70"><span className="sr-only">{unavailable}</span></button>; }

function UsersAccess({ users, query, onQueryChange, missingFields, error, canView }: { users: SettingsUser[]; query: string; onQueryChange: (value: string) => void; missingFields: string[]; error: string | null; canView: boolean }) {
  const [selectedId, setSelectedId] = useState<string | null>(null); const [page, setPage] = useState(1); const pageSize = 10;
  const filteredUsers = useMemo(() => users.filter((item) => `${item.name} ${item.email} ${item.role} ${item.id}`.toLowerCase().includes(query.toLowerCase())), [query, users]);
  const pageCount = Math.max(1, Math.ceil(filteredUsers.length / pageSize)); const currentPage = Math.min(page, pageCount); const pageUsers = filteredUsers.slice((currentPage - 1) * pageSize, currentPage * pageSize); const selectedUser = users.find((item) => item.id === selectedId) ?? pageUsers[0] ?? null;
  useEffect(() => { setPage(1); }, [query]); useEffect(() => { if (pageUsers.length && !selectedId) setSelectedId(pageUsers[0].id); }, [pageUsers, selectedId]);
  return <><KpiCards totalUsers={canView && !error ? users.length : null} /><div className="grid min-w-0 gap-4 xl:grid-cols-[minmax(0,1.7fr)_minmax(360px,0.8fr)]"><section className="min-w-0 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex min-w-[260px] flex-1 items-center gap-2 rounded-lg border border-blue-100 px-3 py-2 text-sm text-slate-500"><Search size={17} /><input aria-label="Search users by name, email or employee ID" value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder="Search users by name, email or employee ID..." className="min-w-0 flex-1 bg-transparent outline-none" /></div><div className="flex gap-2"><ActionButton icon={<Plus size={16} />} label="Add User" /><ActionButton icon={<Mail size={16} />} label="Invite User" /><ActionButton icon={<Upload size={16} />} label="Import Users" /><IconButton icon={<MoreHorizontal size={18} />} label="More user actions" /></div></div><div className="mt-2 flex flex-wrap gap-2"><FilterSelect label="All Departments" /><FilterSelect label="All Roles" /><FilterSelect label="All Statuses" /><button type="button" disabled className="inline-flex items-center gap-2 rounded-lg border border-blue-100 bg-blue-50 px-3 py-2 text-xs font-semibold text-blue-700 disabled:cursor-not-allowed disabled:opacity-70"><Filter size={15} />More Filters</button></div>{!canView ? <p className="mt-4 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800">Admin access is required to view user administration.</p> : null}{error ? <p role="alert" className="mt-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p> : null}<p className="mt-4 text-xs text-slate-500">Showing {pageUsers.length ? (currentPage - 1) * pageSize + 1 : 0} - {(currentPage - 1) * pageSize + pageUsers.length} of {filteredUsers.length} users</p><div className="mt-2 overflow-x-auto"><table className="w-full min-w-[940px] text-left text-xs"><thead className="bg-blue-50/70 text-blue-950 dark:bg-slate-800 dark:text-slate-200"><tr><th className="p-3"><input type="checkbox" disabled aria-label="Select all users unavailable" /></th>{["User Name", "Employee ID", "Email", "Department", "Role", "Status", "Last Login", "MFA", "Actions"].map((label) => <th key={label} className="p-3 font-semibold">{label}</th>)}</tr></thead><tbody>{canView && pageUsers.map((item) => <tr key={item.id} onClick={() => setSelectedId(item.id)} className={`cursor-pointer border-b border-blue-50 transition hover:bg-blue-50/50 dark:border-slate-800 ${selectedUser?.id === item.id ? "bg-blue-50/80 dark:bg-slate-800" : ""}`}><td className="p-3"><input type="checkbox" disabled checked={false} onChange={() => undefined} aria-label={`Select ${item.name} unavailable`} /></td><td className="p-3"><div className="flex items-center gap-2"><Avatar user={item} /><span className="font-semibold text-blue-950 dark:text-white">{item.name}</span></div></td><td className="p-3">{item.employeeId ?? unavailable}</td><td className="p-3">{item.email}</td><td className="p-3">{item.department ?? unavailable}</td><td className="p-3">{item.role}</td><td className="p-3"><StatusBadge value={item.accountStatus} /></td><td className="p-3">{item.lastLoginAt ?? unavailable}</td><td className="p-3"><StatusBadge value={item.mfaStatus} /></td><td className="p-3"><button type="button" disabled aria-label={`Actions for ${item.name}`} className="text-blue-700 disabled:cursor-not-allowed disabled:opacity-60"><MoreVertical size={17} /></button></td></tr>)}{canView && !pageUsers.length ? <tr><td colSpan={10} className="p-8 text-center text-slate-500">No verified user records available.</td></tr> : null}</tbody></table></div><Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />{missingFields.length ? <p className="mt-3 text-xs text-slate-500">Missing fields: {missingFields.join(", ")}. Values are not inferred.</p> : null}</section><UserDetails user={selectedUser} /></div></>;
}

function KpiCards({ totalUsers }: { totalUsers: number | null }) { const cards = [[Users, "Total Users", totalUsers === null ? unavailable : String(totalUsers), totalUsers === null ? "Verified database count unavailable" : "Loaded user records", "blue"], [UserRound, "Active Users", unavailable, "Account status unavailable", "green"], [ClockIcon, "Pending Invitations", unavailable, "Invitation contract unavailable", "amber"], [LockKeyhole, "Locked Accounts", unavailable, "Account status unavailable", "red"], [Shield, "MFA Enabled", unavailable, "MFA field unavailable", "purple"]] as const; return <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">{cards.map(([Icon, label, value, detail, color]) => <div key={label} className="flex min-h-[112px] items-center gap-3 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-lg text-white ${color === "green" ? "bg-emerald-600" : color === "amber" ? "bg-amber-500" : color === "red" ? "bg-red-500" : color === "purple" ? "bg-violet-600" : "bg-blue-600"}`}><Icon size={25} /></div><div className="min-w-0"><p className="text-xs font-semibold text-blue-900 dark:text-blue-200">{label}</p><p className="mt-1 text-2xl font-bold text-blue-950 dark:text-white">{value}</p><p className="text-[10px] text-slate-500">{detail}</p></div>{label === "MFA Enabled" ? <div className="ml-auto flex h-12 w-12 shrink-0 items-center justify-center rounded-full border-4 border-blue-100 text-[10px] font-bold text-blue-700">N/A</div> : null}</div>)}</div>; }

function UserDetails({ user }: { user: SettingsUser | null }) { const fields: Array<[string, string]> = user ? [["Full Name", user.name], ["Employee ID", user.employeeId ?? unavailable], ["Email Address", user.email], ["Department", user.department ?? unavailable], ["Job Title", unavailable], ["Phone Number", unavailable], ["Location", unavailable], ["Time Zone", user.defaultTimezone ?? unavailable], ["Account Created", user.createdAt], ["Last Login", user.lastLoginAt ?? unavailable], ["MFA", user.mfaStatus ?? unavailable]] : []; return <aside className="min-w-0 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className="flex items-start justify-between gap-3">{user ? <div className="flex items-center gap-3"><Avatar user={user} large /><div><h2 className="text-lg font-semibold text-blue-950 dark:text-white">{user.name}</h2><p className="text-xs text-slate-500">{user.role} <span className="mx-1">|</span> {user.id}</p></div></div> : <h2 className="text-lg font-semibold text-blue-950 dark:text-white">User Details</h2>}<button type="button" disabled aria-label="Close user details" className="text-slate-400 disabled:cursor-not-allowed"><X size={19} /></button></div><div className="mt-4 grid grid-cols-4 border-b border-blue-100 text-[11px] font-semibold text-blue-700">{["Profile", "Access & Permissions", "Access Scope", "Activity Log"].map((tab, index) => <button key={tab} type="button" disabled={index !== 0} className={`border-b-2 px-1 py-3 ${index === 0 ? "border-blue-600" : "border-transparent opacity-60"}`}>{tab}</button>)}</div><div className="mt-4 rounded-lg border border-blue-100 p-3"><div className="mb-3 flex items-center justify-between"><h3 className="font-semibold text-blue-950 dark:text-white">User Information</h3><button type="button" disabled className="inline-flex items-center gap-1 text-xs font-semibold text-blue-700 disabled:cursor-not-allowed disabled:opacity-60"><Edit3 size={14} />Edit</button></div><dl className="space-y-2 text-xs">{fields.map(([label, value]) => <div key={label} className="grid grid-cols-[1fr_1.25fr] gap-2"><dt className="text-slate-500">{label}</dt><dd className="break-words text-blue-950 dark:text-slate-200">{value}</dd></div>)}</dl></div><div className="mt-4 flex flex-wrap gap-2"><ActionButton icon={<Edit3 size={15} />} label="Edit User" /><ActionButton icon={<KeyRound size={15} />} label="Reset Password" /><ActionButton icon={<ChevronDown size={15} />} label="More Actions" /></div></aside>; }

function Avatar({ user, large = false }: { user: SettingsUser; large?: boolean }) { return <div className={`flex shrink-0 items-center justify-center rounded-full bg-blue-100 font-bold text-blue-700 ${large ? "h-16 w-16 text-xl" : "h-8 w-8 text-[11px]"}`}>{user.name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase()}</div>; }
function StatusBadge({ value }: { value: string | null }) { return value ? <span className="rounded-full bg-emerald-100 px-2 py-1 text-[10px] font-semibold text-emerald-700">{value}</span> : <span className="text-slate-500">{unavailable}</span>; }
function FilterSelect({ label }: { label: string }) { return <button type="button" disabled className="inline-flex min-w-[150px] items-center justify-between gap-3 rounded-lg border border-blue-100 bg-white px-3 py-2 text-xs text-slate-500 disabled:cursor-not-allowed disabled:bg-slate-50"><span>{label}</span><ChevronDown size={14} /></button>; }
function ActionButton({ icon, label }: { icon: React.ReactNode; label: string }) { return <button type="button" disabled className="inline-flex items-center gap-1.5 rounded-lg border border-blue-500 bg-white px-3 py-2 text-xs font-semibold text-blue-700 disabled:cursor-not-allowed disabled:opacity-60">{icon}{label}</button>; }
function IconButton({ icon, label }: { icon: React.ReactNode; label: string }) { return <button type="button" disabled aria-label={label} className="rounded-lg border border-blue-500 bg-white p-2 text-blue-700 disabled:cursor-not-allowed disabled:opacity-60">{icon}</button>; }
function Pagination({ page, pageCount, onPageChange }: { page: number; pageCount: number; onPageChange: (page: number) => void }) { return <div className="mt-4 flex items-center justify-end gap-1 text-xs"><button type="button" disabled={page <= 1} onClick={() => onPageChange(page - 1)} className="rounded-lg border border-slate-200 p-2 text-blue-700 disabled:opacity-40"><ChevronLeft size={15} /></button>{Array.from({ length: pageCount }, (_, index) => index + 1).slice(0, 5).map((value) => <button type="button" key={value} onClick={() => onPageChange(value)} className={`h-8 w-8 rounded-lg border ${value === page ? "border-blue-600 bg-blue-600 text-white" : "border-slate-200 text-blue-700"}`}>{value}</button>)}<button type="button" disabled={page >= pageCount} onClick={() => onPageChange(page + 1)} className="rounded-lg border border-slate-200 p-2 text-blue-700 disabled:opacity-40"><ChevronRight size={15} /></button></div>; }
function SystemConfiguration({ data, error, canView }: { data: SettingsSystemConfigurationResponse | null; error: string | null; canView: boolean }) {
  const featureFlags = ["Advanced Analytics", "Field Inspection App", "Risk Modeling", "API Access", "Beta Features", "Legacy Reports"];
  return <div className="space-y-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5"><SystemKpi icon={<CircleCheck size={25} />} label="Environment Status" value={unavailable} detail="Production environment status unavailable" tone="green" /><SystemKpi icon={<Database size={25} />} label="Connected Services" value={unavailable} detail="Service health contract unavailable" tone="blue" /><SystemKpi icon={<Database size={25} />} label="Backup Health" value={unavailable} detail="Backup status unavailable" tone="purple" /><SystemKpi icon={<KeyRound size={25} />} label="API Keys" value={unavailable} detail="Key metadata unavailable; secrets hidden" tone="amber" /><SystemKpi icon={<FileText size={25} />} label="License Status" value={unavailable} detail="License contract unavailable" tone="teal" /></div><div className="grid gap-4 xl:grid-cols-5"><ConfigSection title="General System Settings" subtitle="Basic platform configuration and system information" icon={<Cog size={20} />}><ConfigField label="Platform Name" value={unavailable} /><ConfigField label="System Description" value={unavailable} multiline /><ConfigField label="Base URL" value={unavailable} /><ConfigField label="Contact Email" value={unavailable} /></ConfigSection><ConfigSection title="Branding & Appearance" subtitle="Customize platform branding and theme" icon={<Settings size={20} />}><ConfigField label="Company Logo" value={unavailable} /><ConfigField label="Primary Color" value={unavailable} /><ConfigField label="Theme" value={unavailable} /><ConfigField label="Login Message" value={unavailable} multiline /></ConfigSection><ConfigSection title="Regional & Localization" subtitle="Configure regional settings and default formats" icon={<Globe2 size={20} />}><ConfigSelect label="Default Timezone" value={unavailable} /><ConfigSelect label="Date Format" value={unavailable} /><ConfigSelect label="Time Format" value={unavailable} /><ConfigSelect label="Default Language" value={unavailable} /><ConfigSelect label="Default Units" value={unavailable} /></ConfigSection><ConfigSection title="Security Policies" subtitle="Configure security and access policies" icon={<ShieldCheck size={20} />}><ConfigToggle label="Enforce Multi-Factor Authentication (MFA)" /><ConfigToggle label="Password Complexity Requirements" /><ConfigField label="Password Expiry (days)" value={unavailable} /><ConfigToggle label="Prevent Reuse of Previous Passwords" /><ConfigField label="Account Lockout (failed attempts)" value={unavailable} /><ConfigField label="Lockout Duration (minutes)" value={unavailable} /><ConfigToggle label="Allow Single Sign-On (SSO)" /><ConfigField label="IP Whitelist (optional)" value={unavailable} multiline /></ConfigSection><ConfigSection title="Session & Access Control" subtitle="Configure user session and access behaviour" icon={<ClockIcon size={20} />}><ConfigField label="Session Timeout (minutes)" value={unavailable} /><ConfigToggle label="Remember Me (extended session)" /><ConfigField label="Concurrent Session Limit" value={unavailable} /><ConfigToggle label="Show Active Sessions to Users" /><ConfigToggle label="Require Re-Authentication for Sensitive Actions" /></ConfigSection></div><div className="grid gap-4 xl:grid-cols-3"><ConfigSection title="Integration Endpoints" subtitle="Display connector status; credentials remain in Integration Hub" icon={<Link2 size={20} />}><div className="space-y-2">{["Mapping Service (WMS)", "Analytics Service", "Email Service (SMTP)", "Notification Webhook", "Identity Provider (SSO)"].map((label) => <div key={label} className="grid grid-cols-[1.15fr_1fr_auto] items-center gap-2 text-xs"><span className="font-semibold text-blue-900 dark:text-blue-200">{label}</span><span className="truncate rounded border border-blue-100 px-2 py-2 text-slate-500">{unavailable}</span><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] text-slate-500">{unavailable}</span></div>)}</div></ConfigSection><ConfigSection title="Storage Settings" subtitle="Configure file storage and data retention" icon={<Database size={20} />}><ConfigSelect label="Storage Type" value={unavailable} /><ConfigField label="Bucket / Container" value={unavailable} /><ConfigField label="Region" value={unavailable} /><ConfigField label="Access Key" value="Not Displayed" /><ConfigField label="Secret Key" value="Not Displayed" /></ConfigSection><ConfigSection title="Backup & Recovery" subtitle="Configure automated backups and recovery options" icon={<RotateCcw size={20} />}><ConfigSelect label="Backup Schedule" value={unavailable} /><ConfigSelect label="Backup Time (UTC)" value={unavailable} /><ConfigSelect label="Retention Period (days)" value={unavailable} /><ConfigToggle label="Include Database" /><ConfigToggle label="Include File Storage" /><ConfigToggle label="Include Configuration" /><div className="mt-3 flex gap-2"><ActionButton icon={<Download size={15} />} label="Backup Now" /><ActionButton icon={<RotateCcw size={15} />} label="Restore Settings" /></div></ConfigSection></div><div className="grid gap-4 xl:grid-cols-[1fr_1fr]"><ConfigSection title="Feature Flags" subtitle="Enable or disable platform features" icon={<Flag size={20} />}><div className="grid gap-2 sm:grid-cols-2">{featureFlags.map((label) => <ConfigToggle key={label} label={label} />)}</div></ConfigSection><ConfigSection title="Environment Variables" subtitle="Current environment variables (read-only)" icon={<Wrench size={20} />}><div className="rounded-lg bg-slate-950 p-3 font-mono text-[11px] text-slate-300"><p>{unavailable}</p><p className="mt-1 text-slate-500">Secrets and credentials are never displayed.</p></div></ConfigSection></div><div className="flex flex-wrap items-center justify-end gap-2 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><ActionButton icon={<RotateCcw size={15} />} label="Reset to Defaults" /><button type="button" disabled className="rounded-lg border border-blue-500 px-4 py-2 text-xs font-semibold text-blue-700 disabled:cursor-not-allowed disabled:opacity-60">Cancel</button><button type="button" disabled className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-xs font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60"><Download size={15} />Save Changes</button></div>{!canView ? <p className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800">Admin access is required to view system configuration.</p> : null}{error ? <p role="alert" className="rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-700">{error}</p> : null}<p className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800">Configuration data is unavailable in the current backend contract. Unsupported controls are disabled. High-impact changes require Draft → Impact Review → Approval → Effective Date → Activation. Integration Hub owns connector credentials and endpoints; secrets are not exposed.</p>{data?.missingFields.length ? <p className="text-xs text-slate-500">Missing fields: {data.missingFields.join(", ")}. Values are not inferred.</p> : null}</div>;
}

function SystemKpi({ icon, label, value, detail, tone }: { icon: React.ReactNode; label: string; value: string; detail: string; tone: "green" | "blue" | "purple" | "amber" | "teal" }) { const colors = { green: "bg-emerald-600", blue: "bg-blue-600", purple: "bg-violet-600", amber: "bg-amber-500", teal: "bg-teal-600" }; return <div className="flex min-h-[112px] items-center gap-3 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-lg text-white ${colors[tone]}`}>{icon}</div><div><p className="text-xs font-semibold text-blue-900 dark:text-blue-200">{label}</p><p className="mt-1 text-xl font-bold text-blue-950 dark:text-white">{value}</p><p className="text-[10px] text-slate-500">{detail}</p></div></div>; }
function ConfigSection({ title, subtitle, icon, children }: { title: string; subtitle: string; icon: React.ReactNode; children: React.ReactNode }) { return <section className="rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className="mb-4 flex items-start gap-2"><span className="text-blue-600">{icon}</span><div><h2 className="text-sm font-semibold text-blue-950 dark:text-white">{title}</h2><p className="text-[10px] text-slate-500">{subtitle}</p></div></div>{children}</section>; }
function ConfigField({ label, value, multiline = false }: { label: string; value: string; multiline?: boolean }) { return <label className="mb-2 block text-[10px] font-semibold text-blue-900 dark:text-blue-200">{label}<span className={`mt-1 block rounded border border-blue-100 px-2 py-2 font-normal text-slate-500 ${multiline ? "min-h-12" : ""}`}>{value}</span></label>; }
function ConfigSelect({ label, value }: { label: string; value: string }) { return <label className="mb-2 block text-[10px] font-semibold text-blue-900 dark:text-blue-200">{label}<span className="mt-1 flex items-center justify-between rounded border border-blue-100 px-2 py-2 font-normal text-slate-500">{value}<ChevronDown size={13} /></span></label>; }
function ConfigToggle({ label }: { label: string }) { return <div className="flex items-center justify-between gap-2 border-b border-blue-50 py-2 text-[10px] text-blue-900 dark:border-slate-800 dark:text-blue-200"><span>{label}</span><button type="button" disabled aria-label={`${label}: ${unavailable}`} className="h-5 w-9 shrink-0 rounded-full border border-slate-300 bg-slate-100 disabled:cursor-not-allowed disabled:opacity-70"><span className="sr-only">{unavailable}</span></button></div>; }

function AuditLog({ data, error, canView }: { data: SettingsAuditLogResponse | null; error: string | null; canView: boolean }) {
  const filters = ["User", "Module", "Event Type", "Severity", "Date Range", "Object ID"];
  const columns = ["Timestamp", "User", "Module", "Action", "Record ID", "Before / After", "IP Address", "Result", "Details"];
  return <div className="space-y-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5"><AuditKpi icon={<FileText size={25} />} label="Total Events" value={unavailable} detail="Verified audit event count unavailable" tone="blue" /><AuditKpi icon={<AlertTriangle size={25} />} label="High-Risk Events" value={unavailable} detail="Severity data unavailable" tone="red" /><AuditKpi icon={<Cog size={25} />} label="Configuration Changes" value={unavailable} detail="Action data unavailable" tone="blue" /><AuditKpi icon={<UserRound size={25} />} label="Login Events" value={unavailable} detail="Login event data unavailable" tone="green" /><AuditKpi icon={<LockKeyhole size={25} />} label="Failed Attempts" value={unavailable} detail="Result data unavailable" tone="orange" /></div><section className="rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="text-xl font-semibold text-blue-950 dark:text-white">Filters</h2><div className="flex flex-wrap gap-2"><ActionButton icon={<Filter size={15} />} label="Save Filter" /><ActionButton icon={<RotateCcw size={15} />} label="Retention Settings" /><ActionButton icon={<ShieldCheck size={15} />} label="Integrity Verification" /><ActionButton icon={<Download size={15} />} label="Export Log" /></div></div><div className="mt-4 grid gap-2 md:grid-cols-2 xl:grid-cols-6">{filters.map((label) => <button key={label} type="button" disabled className="flex items-center justify-between rounded-lg border border-blue-100 px-3 py-3 text-left text-xs text-slate-500 disabled:cursor-not-allowed disabled:bg-slate-50"><span>{label}: {unavailable}</span><ChevronDown size={14} /></button>)}</div><div className="mt-3 flex items-center justify-between text-xs text-slate-500"><span>Active filters: {unavailable}</span><span>Showing 0 of {unavailable} events</span></div></section><section className="rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className="overflow-x-auto"><table className="w-full min-w-[1100px] text-left text-xs"><thead className="bg-blue-50/70 text-blue-950 dark:bg-slate-800 dark:text-slate-200"><tr><th className="p-3"> </th>{columns.map((column) => <th key={column} className="p-3 font-semibold">{column}</th>)}<th className="p-3"> </th></tr></thead><tbody><tr><td colSpan={columns.length + 2} className="p-12 text-center text-slate-500">{canView ? "No verified audit events available." : "Admin access is required to view the audit log."}</td></tr></tbody></table></div><div className="mt-3 flex items-center justify-between text-xs text-slate-500"><span>Rows per page: {unavailable}</span><Pagination page={1} pageCount={1} onPageChange={() => undefined} /></div></section><section className="grid gap-4 xl:grid-cols-3"><div className="rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900 xl:col-span-2"><div className="flex items-center justify-between"><h2 className="text-lg font-semibold text-blue-950 dark:text-white">Event Details</h2><button type="button" disabled className="text-slate-400 disabled:cursor-not-allowed"><X size={18} /></button></div><div className="mt-3 grid gap-3 md:grid-cols-2"><AuditDetail label="Audit_Event_ID" /><AuditDetail label="User_ID" /><AuditDetail label="Timestamp" /><AuditDetail label="Module" /><AuditDetail label="Action" /><AuditDetail label="Record ID / Object ID" /><AuditDetail label="IP Address" /><AuditDetail label="Result" /><AuditDetail label="Severity" /><AuditDetail label="Session ID" /><AuditDetail label="Request ID" /><AuditDetail label="User Agent" /></div><div className="mt-4 grid gap-3 md:grid-cols-2"><AuditValue title="Before" /><AuditValue title="After" /></div></div><div className="rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><h2 className="text-lg font-semibold text-blue-950 dark:text-white">Affected Record</h2><div className="mt-3 rounded-lg border border-blue-100 p-3"><p className="text-xs font-semibold text-blue-700">{unavailable}</p><p className="mt-1 text-xs text-slate-500">Owning module reference: {unavailable}</p><button type="button" disabled className="mt-3 text-xs font-semibold text-blue-700 disabled:cursor-not-allowed disabled:opacity-60">Open in owning module ↗</button></div><h3 className="mt-4 text-sm font-semibold text-blue-950 dark:text-white">Additional Information</h3><AuditDetail label="Details" /><AuditDetail label="Integrity verification" /></div></section>{error ? <p role="alert" className="rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-700">{error}</p> : null}<p className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800">The central Audit Log is append-only. No events, timestamps, counts or before/after values are fabricated. Unsupported filters, exports and event actions are disabled.</p>{data?.missingFields.length ? <p className="text-xs text-slate-500">Missing fields: {data.missingFields.join(", ")}. Values are not inferred.</p> : null}</div>;
}

function AuditKpi({ icon, label, value, detail, tone }: { icon: React.ReactNode; label: string; value: string; detail: string; tone: "blue" | "red" | "green" | "orange" }) { const colors = { blue: "bg-blue-600", red: "bg-red-500", green: "bg-emerald-600", orange: "bg-orange-500" }; return <div className="flex min-h-[112px] items-center gap-3 rounded-xl border border-blue-100 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900"><div className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-lg text-white ${colors[tone]}`}>{icon}</div><div><p className="text-xs font-semibold text-blue-900 dark:text-blue-200">{label}</p><p className="mt-1 text-2xl font-bold text-blue-950 dark:text-white">{value}</p><p className="text-[10px] text-slate-500">{detail}</p></div></div>; }
function AuditDetail({ label }: { label: string }) { return <div className="flex justify-between gap-3 border-b border-blue-50 py-1.5 text-xs"><span className="text-slate-500">{label}</span><span className="text-right text-blue-950 dark:text-slate-200">{unavailable}</span></div>; }
function AuditValue({ title }: { title: string }) { return <div className="min-h-24 rounded-lg border border-blue-100 p-3"><h3 className="text-xs font-semibold text-blue-700">{title}</h3><p className="mt-2 font-mono text-[11px] text-slate-500">{unavailable}</p></div>; }

function UnavailableTab({ title }: { title: string }) { return <section className="rounded-xl border border-blue-100 bg-white p-8 shadow-sm dark:border-slate-800 dark:bg-slate-900"><h2 className="text-xl font-semibold">{title}</h2><p className="mt-3 text-sm text-slate-500">This tab is reserved in the approved Settings order. Its data contract and owning API are not available yet. No demo values or write actions are shown.</p></section>; }
function ClockIcon({ size }: { size?: number }) { return <svg aria-hidden="true" height={size} width={size} fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></svg>; }
